input.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');

:root {
  color-scheme: light;
  --ink: #101827;
  --ink-soft: #506078;
  --muted: #8c99aa;
  --paper: #f7f8f4;
  --card: rgba(255, 255, 255, 0.9);
  --line: #e4e9e8;
  --line-strong: #d5dddd;
  --lime: #c9ee7b;
  --lime-deep: #9bc756;
  --coral: #ff876f;
  --sky: #94d4ff;
  --violet: #b1a5ff;
  --navy: #101827;
  --city-col: 176px;
  font-family: 'Manrope', 'Avenir Next', ui-sans-serif, system-ui, sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* { box-sizing: border-box; }

body {
  min-width: 320px;
  margin: 0;
  background: var(--paper);
  color: var(--ink);
}

button,
input { font: inherit; }
button { cursor: pointer; }
button:focus-visible,
input:focus-visible,
a:focus-visible { outline: 3px solid rgba(255, 135, 111, 0.55); outline-offset: 3px; }

.app-shell {
  position: relative;
  min-height: 100vh;
  overflow: hidden;
  background:
    radial-gradient(circle at 15% 2%, rgba(201, 238, 123, 0.14), transparent 28rem),
    radial-gradient(circle at 95% 12%, rgba(148, 212, 255, 0.12), transparent 30rem),
    var(--paper);
}

.ambient-glow { position: absolute; pointer-events: none; filter: blur(1px); border-radius: 999px; }
.ambient-glow--top { top: -270px; right: 22%; width: 500px; height: 420px; border: 1px solid rgba(148, 212, 255, 0.16); transform: rotate(-18deg); }
.ambient-glow--bottom { bottom: -290px; left: -130px; width: 520px; height: 420px; border: 1px solid rgba(201, 238, 123, 0.17); transform: rotate(25deg); }

.topbar {
  position: relative;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1320px;
  margin: 0 auto;
  padding: 30px 36px 20px;
}

.brand { display: inline-flex; align-items: center; gap: 11px; color: var(--ink); text-decoration: none; }
.brand-mark {
  display: grid;
  width: 35px;
  height: 35px;
  place-items: center;
  border: 1px solid var(--ink);
  border-radius: 11px;
  background: var(--lime);
  box-shadow: 4px 4px 0 var(--ink);
  font-family: 'Space Grotesk', sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 1;
}
.brand strong { display: block; font-family: 'Space Grotesk', sans-serif; font-size: 16px; letter-spacing: -0.03em; line-height: 1; }
.brand small { display: block; margin-top: 4px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: 0.12em; text-transform: uppercase; }
.topbar-meta { display: flex; align-items: center; gap: 9px; color: #68778b; font-family: 'DM Mono', monospace; font-size: 10px; letter-spacing: 0.05em; text-transform: uppercase; }
.live-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--lime-deep); box-shadow: 0 0 0 4px rgba(155, 199, 86, 0.16); }
.meta-divider { width: 1px; height: 18px; margin: 0 5px; background: var(--line-strong); }
.topbar-date { color: var(--ink); }

.page-content { position: relative; z-index: 2; max-width: 1320px; margin: 0 auto; padding: 42px 36px 84px; }
.intro-section { margin: 16px 0 34px; }
.eyebrow { display: flex; align-items: center; gap: 10px; color: #768297; font-family: 'DM Mono', monospace; font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; }
.eyebrow-line { display: inline-block; width: 30px; height: 1px; background: var(--coral); }
.intro-copy { display: flex; align-items: flex-end; justify-content: space-between; gap: 30px; margin-top: 17px; }
h1 { max-width: 730px; margin: 0; font-family: 'Space Grotesk', 'Avenir Next', sans-serif; font-size: clamp(48px, 7.25vw, 91px); font-weight: 600; letter-spacing: -0.075em; line-height: 0.95; }
h1 em { color: var(--coral); font-style: normal; }
.intro-copy p { max-width: 430px; margin: 20px 0 0; color: #68778b; font-size: 15px; line-height: 1.65; }
.intro-signal { display: grid; min-width: 155px; padding: 0 0 6px 20px; border-left: 1px solid var(--line-strong); }
.signal-label { color: var(--muted); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: 0.12em; text-transform: uppercase; }
.intro-signal strong { margin: 4px 0 1px; font-family: 'Space Grotesk', sans-serif; font-size: 38px; letter-spacing: -0.08em; line-height: 1; }
.intro-signal > span:last-child { color: #68778b; font-size: 11px; }

.control-panel {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  min-height: 82px;
  padding: 17px 20px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.72);
  box-shadow: 0 17px 50px rgba(16, 24, 39, 0.04);
  backdrop-filter: blur(14px);
}
.control-date { display: flex; align-items: center; gap: 14px; white-space: nowrap; }
.control-label { display: block; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: 0.13em; text-transform: uppercase; }
.date-field { display: inline-flex; align-items: center; gap: 6px; color: var(--ink); }
.date-field input { width: 120px; padding: 6px 0; border: 0; background: transparent; color: var(--ink); font-family: 'DM Mono', monospace; font-size: 12px; font-weight: 500; }
.date-field input::-webkit-calendar-picker-indicator { opacity: 0.45; }
.date-spelled { color: #758196; font-size: 12px; }
.control-divider { width: 1px; height: 40px; margin: 0 28px; background: var(--line); }
.city-selector { flex: 1; min-width: 0; }
.city-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; margin-top: 7px; }
.city-chip { display: inline-flex; align-items: center; gap: 7px; min-height: 27px; padding: 3px 7px 3px 4px; border: 1px solid #e4e8e5; border-radius: 99px; background: #fff; color: #4d5c72; font-size: 11px; font-weight: 600; }
.chip-initials { display: grid; width: 20px; height: 20px; place-items: center; border-radius: 50%; background: var(--chip-color); color: var(--ink); font-family: 'DM Mono', monospace; font-size: 7px; font-weight: 500; }
.city-chip button { display: grid; width: 17px; height: 17px; place-items: center; margin-left: 1px; padding: 0; border: 0; border-radius: 50%; background: transparent; color: #9aa6b3; }
.city-chip button:hover { background: #f0f2f0; color: var(--ink); }
.add-city-wrap { position: relative; }
.add-city-button { display: inline-flex; align-items: center; gap: 5px; min-height: 28px; padding: 4px 10px 4px 8px; border: 1px dashed #bec8c6; border-radius: 99px; background: transparent; color: #607087; font-size: 11px; font-weight: 700; }
.add-city-button:hover { border-color: var(--ink); color: var(--ink); background: #fff; }
.city-menu { position: absolute; z-index: 10; top: calc(100% + 10px); left: 0; width: 220px; padding: 8px; border: 1px solid var(--line); border-radius: 14px; background: #fff; box-shadow: 0 18px 40px rgba(16, 24, 39, 0.14); }
.menu-label { display: block; padding: 5px 8px 7px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: 0.1em; text-transform: uppercase; }
.city-menu-item { display: flex; align-items: center; width: 100%; gap: 9px; padding: 9px 8px; border: 0; border-radius: 9px; background: transparent; color: var(--ink); font-size: 12px; text-align: left; }
.city-menu-item:hover { background: #f3f6f3; }
.city-menu-item small { margin-left: auto; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 9px; }
.menu-color { width: 7px; height: 7px; border-radius: 50%; }
.empty-menu { display: block; padding: 8px; color: var(--muted); font-size: 11px; }

.planner-layout { display: grid; grid-template-columns: minmax(0, 1.7fr) minmax(310px, 0.63fr); gap: 19px; margin-top: 19px; align-items: start; }
.board-card, .hours-card, .tip-card { border: 1px solid var(--line); border-radius: 20px; background: var(--card); box-shadow: 0 17px 50px rgba(16, 24, 39, 0.045); }
.board-card { min-width: 0; padding: 28px 27px 17px; }
.board-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
.section-kicker { display: block; color: #8995a7; font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: 0.15em; text-transform: uppercase; }
h2 { margin: 8px 0 0; font-family: 'Space Grotesk', sans-serif; font-size: 25px; font-weight: 600; letter-spacing: -0.05em; }
.view-toggle { display: inline-flex; padding: 3px; border: 1px solid var(--line); border-radius: 9px; background: #f5f7f5; }
.view-toggle button { padding: 7px 10px; border: 0; border-radius: 6px; background: transparent; color: #8490a0; font-family: 'DM Mono', monospace; font-size: 9px; }
.view-toggle button.is-active { background: var(--navy); color: #fff; box-shadow: 0 2px 6px rgba(16, 24, 39, 0.18); }
.board-meta-row { display: flex; align-items: center; gap: 17px; margin-top: 22px; color: #738095; font-size: 10px; }
.board-meta-row > span { display: inline-flex; align-items: center; gap: 6px; }
.legend-dot { width: 7px; height: 7px; border-radius: 3px; }
.legend-dot--overlap { background: var(--lime-deep); box-shadow: 0 0 0 3px rgba(155, 199, 86, 0.13); }
.legend-dot--office { background: #cad4d6; }
.board-timezone { margin-left: auto; font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: 0.05em; text-transform: uppercase; }

.timeline-board { margin-top: 24px; overflow: hidden; border: 1px solid var(--line); border-radius: 14px; background: #fbfcfa; }
.timeline-head, .timeline-row { display: grid; grid-template-columns: var(--city-col) minmax(0, 1fr); }
.timeline-head { min-height: 45px; border-bottom: 1px solid var(--line); background: #f6f8f6; }
.city-column-label { display: flex; align-items: center; padding: 0 13px; border-right: 1px solid var(--line); color: #8995a7; font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: 0.11em; }
.axis-column { position: relative; min-width: 0; padding: 13px 0 6px; }
.axis-grid { display: grid; grid-template-columns: repeat(13, minmax(0, 1fr)); color: #8c99aa; font-family: 'DM Mono', monospace; font-size: 9px; }
.axis-grid span { padding-left: 6px; }
.day-marker { position: absolute; bottom: -9px; color: #b2bbc4; font-family: 'DM Mono', monospace; font-size: 7px; letter-spacing: 0.06em; text-transform: uppercase; }
.day-marker--start { left: 4px; }
.day-marker--end { right: 0; }
.timeline-body { position: relative; }
.timeline-row { position: relative; min-height: 72px; border-bottom: 1px solid #edf0ee; }
.timeline-row:last-child { border-bottom: 0; }
.city-label { z-index: 2; display: flex; align-items: center; gap: 9px; padding: 11px 13px; border-right: 1px solid var(--line); background: rgba(251, 252, 250, 0.9); }
.city-avatar { display: grid; width: 28px; height: 28px; flex: 0 0 auto; place-items: center; border-radius: 9px; background: var(--city-soft); color: var(--city-color); font-family: 'DM Mono', monospace; font-size: 8px; font-weight: 500; }
.city-label-copy { min-width: 0; }
.city-label-copy strong { display: block; overflow: hidden; color: var(--ink); font-size: 11px; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.city-label-copy small { display: block; margin-top: 4px; overflow: hidden; color: #8995a7; font-family: 'DM Mono', monospace; font-size: 8px; text-overflow: ellipsis; white-space: nowrap; }
.timeline-track { position: relative; min-width: 0; overflow: hidden; background: linear-gradient(90deg, rgba(248, 250, 247, 0.5), rgba(240, 243, 239, 0.6)); }
.track-grid { position: absolute; inset: 0; display: grid; grid-template-columns: repeat(13, minmax(0, 1fr)); pointer-events: none; }
.track-grid i { border-right: 1px solid rgba(218, 225, 222, 0.8); }
.track-grid i:first-child { border-left: 0; }
.office-range { position: absolute; top: 17px; bottom: 17px; display: flex; align-items: center; min-width: 4px; overflow: hidden; padding: 0 9px; border: 1px solid color-mix(in srgb, var(--range-color) 44%, white); border-radius: 9px; background: color-mix(in srgb, var(--range-color) 14%, white); color: color-mix(in srgb, var(--range-color) 70%, var(--ink)); font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: -0.02em; white-space: nowrap; }
.office-range--overlap { border-color: color-mix(in srgb, var(--range-color) 74%, var(--lime)); background: linear-gradient(90deg, color-mix(in srgb, var(--range-color) 20%, white), rgba(201, 238, 123, 0.72)); color: var(--ink); box-shadow: inset 0 0 0 1px rgba(255,255,255,.35); }
.overlap-band { position: absolute; z-index: 1; top: 0; bottom: 0; border-right: 1px solid rgba(155, 199, 86, 0.17); border-left: 1px solid rgba(155, 199, 86, 0.17); background: rgba(201, 238, 123, 0.09); pointer-events: none; }
.overlap-band span { position: absolute; top: 6px; left: 7px; color: #8cad4e; font-family: 'DM Mono', monospace; font-size: 7px; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; }
.now-line { position: absolute; z-index: 4; top: 0; bottom: 0; width: 1px; background: var(--coral); box-shadow: 0 0 0 1px rgba(255, 135, 111, 0.12); pointer-events: none; }
.now-line::before { position: absolute; top: -5px; left: -3px; width: 7px; height: 7px; border-radius: 50%; background: var(--coral); content: ''; }
.now-line span { position: absolute; top: -16px; left: 5px; color: var(--coral); font-family: 'DM Mono', monospace; font-size: 7px; letter-spacing: .07em; text-transform: uppercase; }
.board-footer { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding-top: 16px; color: #929daa; font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: .04em; }
.board-footer span { display: inline-flex; align-items: center; gap: 6px; }

.insight-column { display: grid; gap: 19px; }
.sweet-spot-card { position: relative; overflow: hidden; padding: 24px 23px 21px; border: 1px solid var(--ink); border-radius: 20px; background: var(--lime); box-shadow: 5px 5px 0 rgba(16, 24, 39, 0.9); }
.sweet-spot-card::after { position: absolute; right: -36px; bottom: -45px; width: 160px; height: 160px; border: 1px solid rgba(16, 24, 39, 0.15); border-radius: 50%; content: ''; box-shadow: 0 0 0 17px rgba(16, 24, 39, 0.03), 0 0 0 35px rgba(16, 24, 39, 0.025); }
.card-topline { position: relative; z-index: 1; display: flex; align-items: center; gap: 8px; color: #3e5424; font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .11em; text-transform: uppercase; }
.sun-badge { display: grid; width: 27px; height: 27px; place-items: center; border: 1px solid rgba(16, 24, 39, 0.18); border-radius: 9px; background: rgba(255, 255, 255, 0.36); color: var(--ink); }
.sparkle { margin-left: auto; color: #647b3a; font-size: 14px; }
.overlap-time { position: relative; z-index: 1; margin: 22px 0 3px; font-family: 'Space Grotesk', sans-serif; font-size: clamp(26px, 3vw, 35px); font-weight: 600; letter-spacing: -0.08em; line-height: 1; }
.overlap-time span { padding: 0 4px; color: #738c49; font-family: 'Manrope', sans-serif; font-size: 18px; font-weight: 400; letter-spacing: 0; }
.overlap-time--empty { font-size: 30px; letter-spacing: -0.06em; }
.overlap-zone { position: relative; z-index: 1; color: #58713d; font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .04em; }
.local-conversions { position: relative; z-index: 1; display: grid; gap: 8px; margin: 22px 0 21px; padding-top: 16px; border-top: 1px solid rgba(16, 24, 39, 0.16); }
.conversion-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; color: #4b6138; font-size: 10px; }
.conversion-city { display: inline-flex; align-items: center; gap: 7px; }
.conversion-city i { width: 6px; height: 6px; border-radius: 2px; }
.conversion-row strong { color: var(--ink); font-family: 'DM Mono', monospace; font-size: 9px; font-weight: 500; }
.primary-action { position: relative; z-index: 1; display: flex; align-items: center; justify-content: center; width: 100%; gap: 8px; padding: 11px 14px; border: 1px solid var(--ink); border-radius: 9px; background: var(--ink); color: #fff; font-size: 11px; font-weight: 700; transition: transform .18s ease, background .18s ease; }
.primary-action:hover { transform: translateY(-2px); background: #273245; }

.hours-card { padding: 21px 20px 13px; }
.hours-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; }
h3 { margin: 7px 0 0; font-family: 'Space Grotesk', sans-serif; font-size: 20px; letter-spacing: -0.05em; }
.hours-note { margin-top: 3px; color: #9aa6b3; font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: .08em; text-transform: uppercase; }
.hours-list { margin-top: 16px; }
.hours-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 11px 0; border-bottom: 1px solid #edf0ee; }
.hours-row:last-child { border-bottom: 0; }
.hours-city { display: inline-flex; align-items: center; gap: 8px; min-width: 47px; }
.hours-city strong { font-family: 'DM Mono', monospace; font-size: 9px; font-weight: 500; letter-spacing: .05em; }
.hours-dot { width: 7px; height: 7px; border-radius: 2px; }
.hours-inputs { display: flex; align-items: center; gap: 5px; color: #a4afba; }
.hours-inputs input { width: 81px; padding: 7px 6px; border: 1px solid var(--line); border-radius: 7px; background: #fbfcfa; color: var(--ink); font-family: 'DM Mono', monospace; font-size: 10px; }
.hours-inputs input:focus { border-color: var(--coral); outline: 0; }
.hours-inputs input::-webkit-calendar-picker-indicator { opacity: .4; }
.tip-card { display: flex; align-items: flex-start; gap: 11px; padding: 16px 17px; background: #f0f4ef; box-shadow: none; }
.tip-mark { display: grid; width: 23px; height: 23px; flex: 0 0 auto; place-items: center; border-radius: 7px; background: var(--ink); color: var(--lime); font-family: 'Space Grotesk', sans-serif; font-size: 15px; }
.tip-card strong { display: block; margin: 1px 0 4px; font-size: 11px; }
.tip-card p { max-width: 245px; margin: 0; color: #7b8997; font-size: 10px; line-height: 1.5; }
.toast { position: fixed; z-index: 20; right: 24px; bottom: 24px; display: flex; align-items: center; gap: 9px; padding: 12px 15px; border: 1px solid var(--ink); border-radius: 10px; background: var(--ink); color: #fff; box-shadow: 0 11px 30px rgba(16, 24, 39, .22); font-size: 11px; animation: toast-in .22s ease-out; }
.toast-check { display: grid; width: 18px; height: 18px; place-items: center; border-radius: 50%; background: var(--lime); color: var(--ink); font-weight: 800; }
@keyframes toast-in { from { transform: translateY(8px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }

@media (max-width: 980px) {
  .page-content { padding-top: 30px; }
  .planner-layout { grid-template-columns: 1fr; }
  .insight-column { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: start; }
  .tip-card { grid-column: 1 / -1; }
}

@media (max-width: 700px) {
  :root { --city-col: 122px; }
  .topbar { padding: 22px 18px 16px; }
  .topbar-meta { font-size: 8px; }
  .topbar-date, .meta-divider { display: none; }
  .page-content { padding: 32px 16px 56px; }
  .intro-section { margin-top: 4px; }
  .intro-copy { display: block; }
  h1 { max-width: 510px; font-size: clamp(44px, 14vw, 72px); }
  .intro-copy p { max-width: 340px; margin-top: 16px; font-size: 13px; }
  .intro-signal { display: flex; align-items: baseline; gap: 7px; width: fit-content; min-width: 0; margin-top: 21px; padding: 0 0 0 12px; }
  .intro-signal strong { font-size: 28px; }
  .signal-label { font-size: 8px; }
  .intro-signal > span:last-child { font-size: 10px; }
  .control-panel { display: block; padding: 16px; }
  .control-date { flex-wrap: wrap; gap: 7px 14px; }
  .date-spelled { flex-basis: 100%; margin-left: 23px; font-size: 11px; }
  .control-divider { width: 100%; height: 1px; margin: 15px 0; }
  .city-chips { margin-top: 9px; }
  .planner-layout { gap: 15px; margin-top: 15px; }
  .board-card { padding: 22px 13px 15px; border-radius: 17px; }
  h2 { font-size: 21px; }
  .board-heading { align-items: flex-end; }
  .view-toggle button { padding: 6px 7px; font-size: 8px; }
  .board-meta-row { flex-wrap: wrap; gap: 9px 13px; margin-top: 18px; }
  .board-timezone { flex-basis: 100%; margin-left: 0; }
  .timeline-board { margin-top: 18px; overflow-x: auto; }
  .timeline-head, .timeline-row { min-width: 650px; }
  .timeline-body { min-width: 650px; }
  .board-footer { display: block; line-height: 1.65; }
  .board-footer span { display: flex; }
  .board-footer span + span { margin-top: 5px; }
  .insight-column { grid-template-columns: 1fr; gap: 15px; }
  .tip-card { grid-column: auto; }
  .sweet-spot-card { padding: 21px 19px 18px; }
  .overlap-time { font-size: 31px; }
  .hours-card { padding: 19px 16px 10px; }
  .hours-inputs input { width: 91px; }
  .toast { right: 16px; bottom: 16px; left: 16px; justify-content: center; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

tool_use_result.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');

:root {
  color-scheme: light;
  --ink: #101827;
  --ink-soft: #506078;
  --muted: #8c99aa;
  --paper: #f7f8f4;
  --card: rgba(255, 255, 255, 0.9);
  --line: #e4e9e8;
  --line-strong: #d5dddd;
  --lime: #c9ee7b;
  --lime-deep: #9bc756;
  --coral: #ff876f;
  --sky: #94d4ff;
  --violet: #b1a5ff;
  --navy: #101827;
  --city-col: 176px;
  font-family: 'Manrope', 'Avenir Next', ui-sans-serif, system-ui, sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* { box-sizing: border-box; }

body {
  min-width: 320px;
  margin: 0;
  background: var(--paper);
  color: var(--ink);
}

button,
input { font: inherit; }
button { cursor: pointer; }
button:focus-visible,
input:focus-visible,
a:focus-visible { outline: 3px solid rgba(255, 135, 111, 0.55); outline-offset: 3px; }

.app-shell {
  position: relative;
  min-height: 100vh;
  overflow: hidden;
  background:
    radial-gradient(circle at 15% 2%, rgba(201, 238, 123, 0.14), transparent 28rem),
    radial-gradient(circle at 95% 12%, rgba(148, 212, 255, 0.12), transparent 30rem),
    var(--paper);
}

.ambient-glow { position: absolute; pointer-events: none; filter: blur(1px); border-radius: 999px; }
.ambient-glow--top { top: -270px; right: 22%; width: 500px; height: 420px; border: 1px solid rgba(148, 212, 255, 0.16); transform: rotate(-18deg); }
.ambient-glow--bottom { bottom: -290px; left: -130px; width: 520px; height: 420px; border: 1px solid rgba(201, 238, 123, 0.17); transform: rotate(25deg); }

.topbar {
  position: relative;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1320px;
  margin: 0 auto;
  padding: 30px 36px 20px;
}

.brand { display: inline-flex; align-items: center; gap: 11px; color: var(--ink); text-decoration: none; }
.brand-mark {
  display: grid;
  width: 35px;
  height: 35px;
  place-items: center;
  border: 1px solid var(--ink);
  border-radius: 11px;
  background: var(--lime);
  box-shadow: 4px 4px 0 var(--ink);
  font-family: 'Space Grotesk', sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 1;
}
.brand strong { display: block; font-family: 'Space Grotesk', sans-serif; font-size: 16px; letter-spacing: -0.03em; line-height: 1; }
.brand small { display: block; margin-top: 4px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: 0.12em; text-transform: uppercase; }
.topbar-meta { display: flex; align-items: center; gap: 9px; color: #68778b; font-family: 'DM Mono', monospace; font-size: 10px; letter-spacing: 0.05em; text-transform: uppercase; }
.live-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--lime-deep); box-shadow: 0 0 0 4px rgba(155, 199, 86, 0.16); }
.meta-divider { width: 1px; height: 18px; margin: 0 5px; background: var(--line-strong); }
.topbar-date { color: var(--ink); }

.page-content { position: relative; z-index: 2; max-width: 1320px; margin: 0 auto; padding: 42px 36px 84px; }
.intro-section { margin: 16px 0 34px; }
.eyebrow { display: flex; align-items: center; gap: 10px; color: #768297; font-family: 'DM Mono', monospace; font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; }
.eyebrow-line { display: inline-block; width: 30px; height: 1px; background: var(--coral); }
.intro-copy { display: flex; align-items: flex-end; justify-content: space-between; gap: 30px; margin-top: 17px; }
h1 { max-width: 730px; margin: 0; font-family: 'Space Grotesk', 'Avenir Next', sans-serif; font-size: clamp(48px, 7.25vw, 91px); font-weight: 600; letter-spacing: -0.075em; line-height: 0.95; }
h1 em { color: var(--coral); font-style: normal; }
.intro-copy p { max-width: 430px; margin: 20px 0 0; color: #68778b; font-size: 15px; line-height: 1.65; }
.intro-signal { display: grid; min-width: 155px; padding: 0 0 6px 20px; border-left: 1px solid var(--line-strong); }
.signal-label { color: var(--muted); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: 0.12em; text-transform: uppercase; }
.intro-signal strong { margin: 4px 0 1px; font-family: 'Space Grotesk', sans-serif; font-size: 38px; letter-spacing: -0.08em; line-height: 1; }
.intro-signal > span:last-child { color: #68778b; font-size: 11px; }

.control-panel {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  min-height: 82px;
  padding: 17px 20px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.72);
  box-shadow: 0 17px 50px rgba(16, 24, 39, 0.04);
  backdrop-filter: blur(14px);
}
.control-date { display: flex; align-items: center; gap: 14px; white-space: nowrap; }
.control-label { display: block; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: 0.13em; text-transform: uppercase; }
.date-field { display: inline-flex; align-items: center; gap: 6px; color: var(--ink); }
.date-field input { width: 120px; padding: 6px 0; border: 0; background: transparent; color: var(--ink); font-family: 'DM Mono', monospace; font-size: 12px; font-weight: 500; }
.date-field input::-webkit-calendar-picker-indicator { opacity: 0.45; }
.date-spelled { color: #758196; font-size: 12px; }
.control-divider { width: 1px; height: 40px; margin: 0 28px; background: var(--line); }
.city-selector { flex: 1; min-width: 0; }
.city-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; margin-top: 7px; }
.city-chip { display: inline-flex; align-items: center; gap: 7px; min-height: 27px; padding: 3px 7px 3px 4px; border: 1px solid #e4e8e5; border-radius: 99px; background: #fff; color: #4d5c72; font-size: 11px; font-weight: 600; }
.chip-initials { display: grid; width: 20px; height: 20px; place-items: center; border-radius: 50%; background: var(--chip-color); color: var(--ink); font-family: 'DM Mono', monospace; font-size: 7px; font-weight: 500; }
.city-chip button { display: grid; width: 17px; height: 17px; place-items: center; margin-left: 1px; padding: 0; border: 0; border-radius: 50%; background: transparent; color: #9aa6b3; }
.city-chip button:hover { background: #f0f2f0; color: var(--ink); }
.add-city-wrap { position: relative; }
.add-city-button { display: inline-flex; align-items: center; gap: 5px; min-height: 28px; padding: 4px 10px 4px 8px; border: 1px dashed #bec8c6; border-radius: 99px; background: transparent; color: #607087; font-size: 11px; font-weight: 700; }
.add-city-button:hover { border-color: var(--ink); color: var(--ink); background: #fff; }
.city-menu { position: absolute; z-index: 10; top: calc(100% + 10px); left: 0; width: 220px; padding: 8px; border: 1px solid var(--line); border-radius: 14px; background: #fff; box-shadow: 0 18px 40px rgba(16, 24, 39, 0.14); }
.menu-label { display: block; padding: 5px 8px 7px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: 0.1em; text-transform: uppercase; }
.city-menu-item { display: flex; align-items: center; width: 100%; gap: 9px; padding: 9px 8px; border: 0; border-radius: 9px; background: transparent; color: var(--ink); font-size: 12px; text-align: left; }
.city-menu-item:hover { background: #f3f6f3; }
.city-menu-item small { margin-left: auto; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 9px; }
.menu-color { width: 7px; height: 7px; border-radius: 50%; }
.empty-menu { display: block; padding: 8px; color: var(--muted); font-size: 11px; }

.planner-layout { display: grid; grid-template-columns: minmax(0, 1.7fr) minmax(310px, 0.63fr); gap: 19px; margin-top: 19px; align-items: start; }
.board-card, .hours-card, .tip-card { border: 1px solid var(--line); border-radius: 20px; background: var(--card); box-shadow: 0 17px 50px rgba(16, 24, 39, 0.045); }
.board-card { min-width: 0; padding: 28px 27px 17px; }
.board-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
.section-kicker { display: block; color: #8995a7; font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: 0.15em; text-transform: uppercase; }
h2 { margin: 8px 0 0; font-family: 'Space Grotesk', sans-serif; font-size: 25px; font-weight: 600; letter-spacing: -0.05em; }
.view-toggle { display: inline-flex; padding: 3px; border: 1px solid var(--line); border-radius: 9px; background: #f5f7f5; }
.view-toggle button { padding: 7px 10px; border: 0; border-radius: 6px; background: transparent; color: #8490a0; font-family: 'DM Mono', monospace; font-size: 9px; }
.view-toggle button.is-active { background: var(--navy); color: #fff; box-shadow: 0 2px 6px rgba(16, 24, 39, 0.18); }
.board-meta-row { display: flex; align-items: center; gap: 17px; margin-top: 22px; color: #738095; font-size: 10px; }
.board-meta-row > span { display: inline-flex; align-items: center; gap: 6px; }
.legend-dot { width: 7px; height: 7px; border-radius: 3px; }
.legend-dot--overlap { background: var(--lime-deep); box-shadow: 0 0 0 3px rgba(155, 199, 86, 0.13); }
.legend-dot--office { background: #cad4d6; }
.board-timezone { margin-left: auto; font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: 0.05em; text-transform: uppercase; }

.timeline-board { margin-top: 24px; overflow: hidden; border: 1px solid var(--line); border-radius: 14px; background: #fbfcfa; }
.timeline-head, .timeline-row { display: grid; grid-template-columns: var(--city-col) minmax(0, 1fr); }
.timeline-head { min-height: 45px; border-bottom: 1px solid var(--line); background: #f6f8f6; }
.city-column-label { display: flex; align-items: center; padding: 0 13px; border-right: 1px solid var(--line); color: #8995a7; font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: 0.11em; }
.axis-column { position: relative; min-width: 0; padding: 13px 0 6px; }
.axis-grid { display: grid; grid-template-columns: repeat(13, minmax(0, 1fr)); color: #8c99aa; font-family: 'DM Mono', monospace; font-size: 9px; }
.axis-grid span { padding-left: 6px; }
.day-marker { position: absolute; bottom: -9px; color: #b2bbc4; font-family: 'DM Mono', monospace; font-size: 7px; letter-spacing: 0.06em; text-transform: uppercase; }
.day-marker--start { left: 4px; }
.day-marker--end { right: 0; }
.timeline-body { position: relative; }
.timeline-row { position: relative; min-height: 72px; border-bottom: 1px solid #edf0ee; }
.timeline-row:last-child { border-bottom: 0; }
.city-label { z-index: 2; display: flex; align-items: center; gap: 9px; padding: 11px 13px; border-right: 1px solid var(--line); background: rgba(251, 252, 250, 0.9); }
.city-avatar { display: grid; width: 28px; height: 28px; flex: 0 0 auto; place-items: center; border-radius: 9px; background: var(--city-soft); color: var(--city-color); font-family: 'DM Mono', monospace; font-size: 8px; font-weight: 500; }
.city-label-copy { min-width: 0; }
.city-label-copy strong { display: block; overflow: hidden; color: var(--ink); font-size: 11px; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.city-label-copy small { display: block; margin-top: 4px; overflow: hidden; color: #8995a7; font-family: 'DM Mono', monospace; font-size: 8px; text-overflow: ellipsis; white-space: nowrap; }
.timeline-track { position: relative; min-width: 0; overflow: hidden; background: linear-gradient(90deg, rgba(248, 250, 247, 0.5), rgba(240, 243, 239, 0.6)); }
.track-grid { position: absolute; inset: 0; display: grid; grid-template-columns: repeat(13, minmax(0, 1fr)); pointer-events: none; }
.track-grid i { border-right: 1px solid rgba(218, 225, 222, 0.8); }
.track-grid i:first-child { border-left: 0; }
.office-range { position: absolute; top: 17px; bottom: 17px; display: flex; align-items: center; min-width: 4px; overflow: hidden; padding: 0 9px; border: 1px solid color-mix(in srgb, var(--range-color) 44%, white); border-radius: 9px; background: color-mix(in srgb, var(--range-color) 14%, white); color: color-mix(in srgb, var(--range-color) 70%, var(--ink)); font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: -0.02em; white-space: nowrap; }
.office-range--overlap { border-color: color-mix(in srgb, var(--range-color) 74%, var(--lime)); background: linear-gradient(90deg, color-mix(in srgb, var(--range-color) 20%, white), rgba(201, 238, 123, 0.72)); color: var(--ink); box-shadow: inset 0 0 0 1px rgba(255,255,255,.35); }
.overlap-band { position: absolute; z-index: 1; top: 0; bottom: 0; border-right: 1px solid rgba(155, 199, 86, 0.17); border-left: 1px solid rgba(155, 199, 86, 0.17); background: rgba(201, 238, 123, 0.09); pointer-events: none; }
.overlap-band span { position: absolute; top: 6px; left: 7px; color: #8cad4e; font-family: 'DM Mono', monospace; font-size: 7px; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; }
.now-line { position: absolute; z-index: 4; top: 0; bottom: 0; width: 1px; background: var(--coral); box-shadow: 0 0 0 1px rgba(255, 135, 111, 0.12); pointer-events: none; }
.now-line::before { position: absolute; top: -5px; left: -3px; width: 7px; height: 7px; border-radius: 50%; background: var(--coral); content: ''; }
.now-line span { position: absolute; top: -16px; left: 5px; color: var(--coral); font-family: 'DM Mono', monospace; font-size: 7px; letter-spacing: .07em; text-transform: uppercase; }
.board-footer { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding-top: 16px; color: #929daa; font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: .04em; }
.board-footer span { display: inline-flex; align-items: center; gap: 6px; }

.insight-column { display: grid; gap: 19px; }
.sweet-spot-card { position: relative; overflow: hidden; padding: 24px 23px 21px; border: 1px solid var(--ink); border-radius: 20px; background: var(--lime); box-shadow: 5px 5px 0 rgba(16, 24, 39, 0.9); }
.sweet-spot-card::after { position: absolute; right: -36px; bottom: -45px; width: 160px; height: 160px; border: 1px solid rgba(16, 24, 39, 0.15); border-radius: 50%; content: ''; box-shadow: 0 0 0 17px rgba(16, 24, 39, 0.03), 0 0 0 35px rgba(16, 24, 39, 0.025); }
.card-topline { position: relative; z-index: 1; display: flex; align-items: center; gap: 8px; color: #3e5424; font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .11em; text-transform: uppercase; }
.sun-badge { display: grid; width: 27px; height: 27px; place-items: center; border: 1px solid rgba(16, 24, 39, 0.18); border-radius: 9px; background: rgba(255, 255, 255, 0.36); color: var(--ink); }
.sparkle { margin-left: auto; color: #647b3a; font-size: 14px; }
.overlap-time { position: relative; z-index: 1; margin: 22px 0 3px; font-family: 'Space Grotesk', sans-serif; font-size: clamp(26px, 3vw, 35px); font-weight: 600; letter-spacing: -0.08em; line-height: 1; }
.overlap-time span { padding: 0 4px; color: #738c49; font-family: 'Manrope', sans-serif; font-size: 18px; font-weight: 400; letter-spacing: 0; }
.overlap-time--empty { font-size: 30px; letter-spacing: -0.06em; }
.overlap-zone { position: relative; z-index: 1; color: #58713d; font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .04em; }
.local-conversions { position: relative; z-index: 1; display: grid; gap: 8px; margin: 22px 0 21px; padding-top: 16px; border-top: 1px solid rgba(16, 24, 39, 0.16); }
.conversion-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; color: #4b6138; font-size: 10px; }
.conversion-city { display: inline-flex; align-items: center; gap: 7px; }
.conversion-city i { width: 6px; height: 6px; border-radius: 2px; }
.conversion-row strong { color: var(--ink); font-family: 'DM Mono', monospace; font-size: 9px; font-weight: 500; }
.primary-action { position: relative; z-index: 1; display: flex; align-items: center; justify-content: center; width: 100%; gap: 8px; padding: 11px 14px; border: 1px solid var(--ink); border-radius: 9px; background: var(--ink); color: #fff; font-size: 11px; font-weight: 700; transition: transform .18s ease, background .18s ease; }
.primary-action:hover { transform: translateY(-2px); background: #273245; }

.hours-card { padding: 21px 20px 13px; }
.hours-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; }
h3 { margin: 7px 0 0; font-family: 'Space Grotesk', sans-serif; font-size: 20px; letter-spacing: -0.05em; }
.hours-note { margin-top: 3px; color: #9aa6b3; font-family: 'DM Mono', monospace; font-size: 8px; letter-spacing: .08em; text-transform: uppercase; }
.hours-list { margin-top: 16px; }
.hours-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 11px 0; border-bottom: 1px solid #edf0ee; }
.hours-row:last-child { border-bottom: 0; }
.hours-city { display: inline-flex; align-items: center; gap: 8px; min-width: 47px; }
.hours-city strong { font-family: 'DM Mono', monospace; font-size: 9px; font-weight: 500; letter-spacing: .05em; }
.hours-dot { width: 7px; height: 7px; border-radius: 2px; }
.hours-inputs { display: flex; align-items: center; gap: 5px; color: #a4afba; }
.hours-inputs input { width: 81px; padding: 7px 6px; border: 1px solid var(--line); border-radius: 7px; background: #fbfcfa; color: var(--ink); font-family: 'DM Mono', monospace; font-size: 10px; }
.hours-inputs input:focus { border-color: var(--coral); outline: 0; }
.hours-inputs input::-webkit-calendar-picker-indicator { opacity: .4; }
.tip-card { display: flex; align-items: flex-start; gap: 11px; padding: 16px 17px; background: #f0f4ef; box-shadow: none; }
.tip-mark { display: grid; width: 23px; height: 23px; flex: 0 0 auto; place-items: center; border-radius: 7px; background: var(--ink); color: var(--lime); font-family: 'Space Grotesk', sans-serif; font-size: 15px; }
.tip-card strong { display: block; margin: 1px 0 4px; font-size: 11px; }
.tip-card p { max-width: 245px; margin: 0; color: #7b8997; font-size: 10px; line-height: 1.5; }
.toast { position: fixed; z-index: 20; right: 24px; bottom: 24px; display: flex; align-items: center; gap: 9px; padding: 12px 15px; border: 1px solid var(--ink); border-radius: 10px; background: var(--ink); color: #fff; box-shadow: 0 11px 30px rgba(16, 24, 39, .22); font-size: 11px; animation: toast-in .22s ease-out; }
.toast-check { display: grid; width: 18px; height: 18px; place-items: center; border-radius: 50%; background: var(--lime); color: var(--ink); font-weight: 800; }
@keyframes toast-in { from { transform: translateY(8px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }

@media (max-width: 980px) {
  .page-content { padding-top: 30px; }
  .planner-layout { grid-template-columns: 1fr; }
  .insight-column { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: start; }
  .tip-card { grid-column: 1 / -1; }
}

@media (max-width: 700px) {
  :root { --city-col: 122px; }
  .topbar { padding: 22px 18px 16px; }
  .topbar-meta { font-size: 8px; }
  .topbar-date, .meta-divider { display: none; }
  .page-content { padding: 32px 16px 56px; }
  .intro-section { margin-top: 4px; }
  .intro-copy { display: block; }
  h1 { max-width: 510px; font-size: clamp(44px, 14vw, 72px); }
  .intro-copy p { max-width: 340px; margin-top: 16px; font-size: 13px; }
  .intro-signal { display: flex; align-items: baseline; gap: 7px; width: fit-content; min-width: 0; margin-top: 21px; padding: 0 0 0 12px; }
  .intro-signal strong { font-size: 28px; }
  .signal-label { font-size: 8px; }
  .intro-signal > span:last-child { font-size: 10px; }
  .control-panel { display: block; padding: 16px; }
  .control-date { flex-wrap: wrap; gap: 7px 14px; }
  .date-spelled { flex-basis: 100%; margin-left: 23px; font-size: 11px; }
  .control-divider { width: 100%; height: 1px; margin: 15px 0; }
  .city-chips { margin-top: 9px; }
  .planner-layout { gap: 15px; margin-top: 15px; }
  .board-card { padding: 22px 13px 15px; border-radius: 17px; }
  h2 { font-size: 21px; }
  .board-heading { align-items: flex-end; }
  .view-toggle button { padding: 6px 7px; font-size: 8px; }
  .board-meta-row { flex-wrap: wrap; gap: 9px 13px; margin-top: 18px; }
  .board-timezone { flex-basis: 100%; margin-left: 0; }
  .timeline-board { margin-top: 18px; overflow-x: auto; }
  .timeline-head, .timeline-row { min-width: 650px; }
  .timeline-body { min-width: 650px; }
  .board-footer { display: block; line-height: 1.65; }
  .board-footer span { display: flex; }
  .board-footer span + span { margin-top: 5px; }
  .insight-column { grid-template-columns: 1fr; gap: 15px; }
  .tip-card { grid-column: auto; }
  .sweet-spot-card { padding: 21px 19px 18px; }
  .overlap-time { font-size: 31px; }
  .hours-card { padding: 19px 16px 10px; }
  .hours-inputs input { width: 91px; }
  .toast { right: 16px; bottom: 16px; left: 16px; justify-content: center; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

